import pandas as pd

def add_margin(frame: pd.DataFrame) -> pd.DataFrame:
    return frame.assign(margin=lambda x: x["revenue"] - x["cost"])

df = pd.DataFrame({"revenue": [100, 200], "cost": [60, 150]})
result = (
    df.pipe(add_margin)
      .query("margin > 20")
)

